WITH valid AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, DATE_FORMAT(starts_on, 'yyyy-MM-dd') AS starts_on_label, CASE WHEN discount_pct >= 0.33 THEN 'High' WHEN discount_pct >= 0.15 THEN 'Medium' ELSE 'Low' END AS discount_pct_tier FROM promotions WHERE channel IS NOT NULL AND channel IS DISTINCT FROM 'store'), scored AS (SELECT *, LAG(discount_pct, 1, 0) OVER (PARTITION BY channel ORDER BY ends_on, id) AS prev_discount_pct, CUME_DIST() OVER (PARTITION BY channel, promo_code ORDER BY discount_pct DESC) AS discount_pct_cume_dist FROM valid), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY prev_discount_pct NULLS FIRST, id) AS row_num FROM scored QUALIFY row_num = 1), deduped_promotions AS (SELECT id, starts_on, ends_on, discount_pct_cume_dist FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY promo_code, channel ORDER BY ends_on DESC, id) AS rank_in_group FROM deduped) t WHERE rank_in_group = 1) SELECT id, starts_on, ends_on FROM deduped_promotions
